    if (p.status === 'ok') {
      const next = { ...st, status: 'recorded', inflight: {} };
      return { ...outOf(next, false), state: next };
    }
    if (p.error?.status === 400 || p.error?.code === 'invalid-args' || p.error?.code === 'field-renamed') {
