  const plan = st && st.status !== 'new' ? {
    orderId: st.order.orderId,
    customerId: st.order.customerId,
    placedAt: st.order.placedAt,
    currency: st.order.currency,
    edition: st.edition,
    totalMinor: st.totalMinor,
    fulfilments: st.fulfilments ?? [],
  } : {};
