        status: rows.find(r => r.fulfilmentId === fid)?.status ?? 'pending', reservations: reservations[fid] ?? [],
        charges: charges[fid] ?? [], refunds: refunds[fid] ?? [], shipments: shipments[fid] ?? [] } } });
    }
  }
  return { subject: oid };
}

