// §3.5: a migrated order that is still waiting for its customer keeps its deadline (the wake-up is re-set). D is
// p + customerActionHours at the edition in force at p (R3.2, S1), as start computes it.
const r = input.records?.customerAction;
if (!r) return outOf(null);
const D = r.D ?? amsIso(Date.parse(r.placedAt) + policyParam(ctx.files, r.edition, 'customerActionHours') * 60 * MIN);
const st = { state: r.state, D, clearedAt: r.clearedAt ?? null, advanced: true, fulfilments: r.fulfilments, at: r.at ?? null, reason: r.reason ?? null };

